    a { color: inherit; text-decoration: none; }

    .container { width: min(100% - 2rem, var(--maxw)); margin-inline: auto; }

    .site-header { position: sticky; top: 0; z-index: 80; backdrop-filter: blur(10px); background: rgba(248,247,255,0.86); border-bottom: 1px solid rgba(118,56,250,0.12); }
    .header-inner { height: 72px; display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
    .brand { display: flex; align-items: center; gap: .65rem; font-weight: 800; letter-spacing: -.02em; }
    .brand-mark { width: 34px; height: 34px; border-radius: 11px; background: linear-gradient(135deg, var(--purple), #af64ff 45%, var(--orange)); }
    .desktop-nav { display: flex; align-items: center; gap: 1.25rem; }
    .desktop-nav a { color: #2f3053; font-weight: 500; }
    .desktop-nav a:hover { color: var(--purple); }
    .header-actions { display: flex; align-items: center; gap: .65rem; }

    .btn { border: 0; border-radius: 999px; padding: .7rem 1.1rem; font-weight: 600; cursor: pointer; font-size: .95rem; }
    .btn-login { background: #eceafc; color: #29264f; }
    .btn-primary { background: linear-gradient(135deg, var(--purple), #9a53ff 50%, var(--orange)); color: #fff; box-shadow: 0 10px 24px rgba(118,56,250,.36); }
    .btn-store { background: #0f1020; color: #fff; padding: .78rem 1.2rem; }

    .hamburger { display: none; width: 42px; height: 42px; border-radius: 12px; border: 1px solid rgba(118,56,250,.2); background: #fff; align-items: center; justify-content: center; cursor: pointer; }
    .hamburger span, .hamburger span::before, .hamburger span::after { display: block; width: 18px; height: 2px; background: #21224c; border-radius: 2px; position: relative; }
    .hamburger span::before, .hamburger span::after { content: ''; position: absolute; left: 0; }
    .hamburger span::before { top: -6px; }
    .hamburger span::after { top: 6px; }

    .mobile-menu { display: none; position: absolute; inset: 72px 1rem auto; border-radius: 16px; background: #fff; box-shadow: var(--shadow); border: 1px solid rgba(118,56,250,.16); padding: 1rem; }
    .mobile-menu.open { display: block; }
    .mobile-menu nav { display: grid; gap: .8rem; }
    .mobile-menu a { padding: .65rem .2rem; border-bottom: 1px solid #f0effa; font-weight: 500; }

    .hero { padding: 4.6rem 0 3.8rem; }
    .hero-wrap { background: radial-gradient(circle at 80% 0%, rgba(255,122,0,.23), transparent 43%), radial-gradient(circle at 15% 10%, rgba(118,56,250,.28), transparent 45%), #fff; border: 1px solid rgba(118,56,250,.16); border-radius: 30px; padding: clamp(2rem, 4vw, 4rem); box-shadow: var(--shadow); }
