    .hero p { margin: 0 0 1.7rem; color: var(--muted); font-size: clamp(1rem, 2vw, 1.2rem); max-width: 64ch; }

    .section { padding: 1.2rem 0 2.4rem; }
    .split { display: grid; gap: 1.1rem; grid-template-columns: 1fr; }
    .panel { background: var(--surface); border: 1px solid rgba(118,56,250,.13); border-radius: var(--radius); padding: 1.4rem; }
    .panel h2 { margin: 0 0 .65rem; font-size: clamp(1.3rem, 2.2vw, 2rem); line-height: 1.12; letter-spacing: -.02em; }
    .panel p { margin: 0 0 .8rem; color: var(--muted); }
    .panel a { color: var(--purple); font-weight: 700; }
    .safety { background: linear-gradient(180deg, #ffffff, #fffaf5); }
    .creators { background: linear-gradient(130deg, #fff, #f7f0ff 75%); }

    .tagline { margin: 1.2rem 0 2.2rem; border-radius: 20px; background: linear-gradient(120deg, #120f2f, #32226a 45%, #7f32d6 70%, #ff7a00); color: #fff; padding: 1.3rem 1.2rem; text-align: center; font-size: clamp(1.05rem, 2.2vw, 1.48rem); font-weight: 700; letter-spacing: -.015em; }

    .news-head { display: flex; align-items: end; justify-content: space-between; gap: 1rem; margin-bottom: .9rem; }
    .eyebrow { font-size: .82rem; text-transform: uppercase; letter-spacing: .12em; color: #6a5fb3; font-weight: 700; }
    .news-head h2 { margin: .2rem 0 0; font-size: clamp(1.45rem, 2.8vw, 2.35rem); letter-spacing: -.03em; }
    .news-head a { color: var(--purple); font-weight: 700; }

    .carousel { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(272px, 30%); gap: 1rem; overflow-x: auto; padding-bottom: .45rem; scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch; }
    .carousel::-webkit-scrollbar { height: 10px; }
    .carousel::-webkit-scrollbar-thumb { background: #cec5fb; border-radius: 999px; }
    .card { background: #fff; border: 1px solid rgba(118,56,250,.14); border-radius: 18px; overflow: hidden; scroll-snap-align: start; min-height: 100%; }
    .thumb { height: 160px; background: linear-gradient(135deg, rgba(118,56,250,.92), rgba(255,122,0,.88)); }
    .card-content { padding: .95rem .95rem 1.1rem; }
    .tags { display: flex; flex-wrap: wrap; gap: .4rem; margin-bottom: .55rem; }
    .tag { background: #efe9ff; color: #4f26ab; font-size: .72rem; font-weight: 700; border-radius: 999px; padding: .28rem .56rem; }
    .card h3 { margin: 0 0 .65rem; font-size: 1rem; line-height: 1.34; }
    .date { font-size: .84rem; color: #5a5b77; }

    .download { margin: 2.4rem 0 2.8rem; background: #fff; border: 1px solid rgba(118,56,250,.16); border-radius: 24px; padding: 1.35rem; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 1rem; }
    .download h2 { margin: 0; font-size: clamp(1.5rem, 3vw, 2.5rem); letter-spacing: -.03em; }
    .download p { margin: .25rem 0 0; color: var(--muted); font-size: 1.05rem; }
    .download-actions { display: flex; flex-wrap: wrap; gap: .65rem; }

    footer { background: #ffffff; border-top: 1px solid rgba(118,56,250,.16); padding: 2.2rem 0 1.3rem; }
    .footer-grid { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 1.2rem 1rem; }
    .footer-col h3 { margin: 0 0 .66rem; font-size: .96rem; }
    .footer-col a { display: block; padding: .2rem 0; color: #4a4c69; font-size: .94rem; }
    .footer-col a:hover { color: var(--purple); }

    .footer-bottom { border-top: 1px solid #ece9ff; margin-top: 1.3rem; padding-top: .95rem; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: .75rem; color: #56577a; font-size: .88rem; }
    .socials { display: flex; gap: .55rem; flex-wrap: wrap; }
    .icon { width: 30px; height: 30px; border-radius: 999px; background: #f0ecff; display: inline-flex; align-items: center; justify-content: center; font-size: .72rem; font-weight: 700; color: #463491; }

    @media (min-width: 900px) {
      .split { grid-template-columns: repeat(3, minmax(0,1fr)); }
      .footer-grid { grid-template-columns: repeat(7, minmax(0,1fr)); }
      .download { padding: 1.8rem 2rem; }
    }

    @media (max-width: 839px) {
      .desktop-nav, .btn-login { display: none; }
      .hamburger { display: inline-flex; }
      .carousel { grid-auto-columns: minmax(255px, 78%); }
    }
  </style>
